{
  "name": "区间列表连接",
  "name_en": "Interval List Connection",
  "manufacturer": "Nion",
  "description": "用于科学图像分析流程中的连接对象，将显示中的区间列表单向绑定到线剖面图形的区间描述信息，以保持相关显示元素之间的同步。",
  "description_en": "A connection object used in scientific image analysis workflows to bind intervals on a display one-way to the interval descriptors of a line profile graphic, keeping related display elements synchronized.",
  "tag_hints": [
    "scientific image analysis",
    "line profile",
    "display intervals",
    "annotation synchronization",
    "data binding",
    "Nion Swift"
  ],
  "actions": [
    {
      "action_name": "auto-source_specifier",
      "description": "获取/设置源对象标识。",
      "description_en": "Get/set the source object specifier."
    },
    {
      "action_name": "auto-target_specifier",
      "description": "获取/设置目标对象标识。",
      "description_en": "Get/set the target object specifier."
    },
    {
      "action_name": "auto-connected_items",
      "description": "获取已连接的项目。",
      "description_en": "Get the connected items."
    },
    {
      "action_name": "auto-detach",
      "description": "断开该连接。",
      "description_en": "Detach the connection."
    },
    {
      "action_name": "auto-reattach",
      "description": "重新附加该连接。",
      "description_en": "Reattach the connection."
    },
    {
      "action_name": "auto-item_inserted",
      "description": "通知连接有项目被插入。",
      "description_en": "Notify the connection that an item was inserted."
    },
    {
      "action_name": "auto-item_removed",
      "description": "通知连接有项目被移除。",
      "description_en": "Notify the connection that an item was removed."
    },
    {
      "action_name": "auto-source_registered",
      "description": "通知连接源对象已注册。",
      "description_en": "Notify the connection that the source object was registered."
    },
    {
      "action_name": "auto-target_registered",
      "description": "通知连接目标对象已注册。",
      "description_en": "Notify the connection that the target object was registered."
    },
    {
      "action_name": "auto-unregistered",
      "description": "通知连接有对象已取消注册。",
      "description_en": "Notify the connection that an object was unregistered."
    }
  ]
}

